namespace scratchbird::engine::sblr { namespace { template<class A> bool nz(const A&a){return std::any_of(a.begin(),a.end(),[](auto b){return b;});} void put(std::vector<std::uint8_t>&o,std::uint64_t v,std::size_t n){for(std::size_t i=0;i<n;++i)o.push_back(static_cast<std::uint8_t>(v>>(8*i)));} std::uint64_t get(const std::uint8_t*b,std::size_t n){std::uint64_t v=0;for(std::size_t i=0;i<n;++i)v|=std::uint64_t(b[i])<<(8*i);return v;} std::array<std::uint8_t,32> digest(const char*d,const std::vector<std::uint8_t>&b){std::vector<std::uint8_t>x(d,d+std::strlen(d));x.insert(x.end(),b.begin(),b.end());return core::hash::ComputeSha256Digest(x).digest;} std::vector<std::uint8_t> pack(const char*m,const std::array<std::uint8_t,376>&b,const char*d){std::vector<std::uint8_t>o={(std::uint8_t)m[0],(std::uint8_t)m[1],(std::uint8_t)m[2],(std::uint8_t)m[3],1,0,0,0};o.insert(o.end(),b.begin(),b.end());std::fill(o.begin()+352,o.begin()+384,0);auto h=digest(d,o);std::copy(h.begin(),h.end(),o.begin()+352);return o;} bool unpack(const std::uint8_t*b,std::size_t n,const char*m,std::array<std::uint8_t,376>*o,const char*d,std::string*e){if(!o||n!=384||std::memcmp(b,m,4)||b[4]!=1){if(e)*e="descriptor invalid";return false;}std::copy_n(b+8,376,o->begin());auto x=pack(m,*o,d);if(!std::equal(x.begin(),x.end(),b)){if(e)*e="descriptor hash invalid";return false;}return true;} }
std::vector<std::uint8_t> EncodeSblrDdlCreateExtensionRequestV1(const SblrDdlCreateExtensionRequestV1&v){if(!nz(v.operation)||!nz(v.receipt)||v.descriptor_length!=384)return{};std::vector<std::uint8_t>o={'S','B','D','Q'};put(o,1,2);put(o,8,2);put(o,7587,4);put(o,574,4);o.insert(o.end(),v.operation.begin(),v.operation.end());o.insert(o.end(),v.receipt.begin(),v.receipt.end());put(o,384,4);o.insert(o.end(),12,0);return o;} bool DecodeSblrDdlCreateExtensionRequestV1(const std::uint8_t*b,std::size_t n,SblrDdlCreateExtensionRequestV1*o,std::string*e){if(!o||n!=64||std::memcmp(b,"SBDQ",4)||get(b+4,2)!=1||get(b+6,2)!=8||get(b+8,4)!=7587||get(b+12,4)!=574){if(e)*e="SBDQ invalid";return false;}SblrDdlCreateExtensionRequestV1 v;std::copy_n(b+16,16,v.operation.begin());std::copy_n(b+32,16,v.receipt.begin());v.descriptor_length=get(b+48,4);if(EncodeSblrDdlCreateExtensionRequestV1(v).empty())return false;*o=v;return true;} std::vector<std::uint8_t> EncodeSblrDdlCreateExtensionDescriptorV1(const SblrDdlCreateExtensionDescriptorV1&v){return nz(v.body)?pack("SBDD",v.body,"SBOD|SBDD|v1"):std::vector<std::uint8_t>{};} bool DecodeSblrDdlCreateExtensionDescriptorV1(const std::uint8_t*b,std::size_t n,SblrDdlCreateExtensionDescriptorV1*o,std::string*e){return o&&unpack(b,n,"SBDD",&o->body,"SBOD|SBDD|v1",e);} std::vector<std::uint8_t> EncodeSblrDdlCreateExtensionResultV1(const SblrDdlCreateExtensionResultV1&v){return nz(v.body)?pack("SLRR",v.body,"ScratchBird.SblrDdlCreateExtension.Result.V1"):std::vector<std::uint8_t>{};} bool DecodeSblrDdlCreateExtensionResultV1(const std::uint8_t*b,std::size_t n,SblrDdlCreateExtensionResultV1*o,std::string*e){return o&&unpack(b,n,"SLRR",&o->body,"ScratchBird.SblrDdlCreateExtension.Result.V1",e);} }
